/* Setwerk – gemeinsame Oberfläche für Android und Browser. */
'use strict';
const G=GymCore,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const KEY='setwerk.v1';let storageFault=false,writeFault=false;
function readState(){try{const raw=window.AndroidGym?AndroidGym.readState():window.SetwerkCloud?SetwerkCloud.readState():localStorage.getItem(KEY);if(!raw)return G.fresh();const s=JSON.parse(raw);if(s.version!==1||!Array.isArray(s.templates)||!Array.isArray(s.sessions))throw Error();return G.migrateState(s);}catch(e){storageFault=true;return G.fresh();}}
let state=readState(),route=state.active?'focus':'home',draft=state.draft||null,selectedDate=G.localDate(),calMonth=selectedDate.slice(0,7),manualMonth=calMonth,search='',muscle='',equipment='',limit=60,selectedExercise='',pickerTarget='',pickerSearch='',pickerMuscle='',modalKind='',viewSession='',toastTimer,exerciseClock=null,wakeLock=null,lastFocus='',nextMotion='',feedbackTarget='',feedbackDraft=null;
const icons={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',dumbbell:'M6 5v14M3 8v8M18 5v14M21 8v8M6 12h12',plus:'M12 5v14M5 12h14',calendar:'M4 5h16v16H4zM8 3v4M16 3v4M4 10h16',chart:'M4 4v16h17M8 16l4-5 4 2 5-8',play:'m8 4 13 8-13 8z',book:'M4 4h7l1 2 1-2h7v16h-7l-1 1-1-1H4zM12 6v15',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',chevron:'m9 5 7 7-7 7',left:'m15 5-7 7 7 7',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',search:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15M16 16l5 5',edit:'m4 16 12-12 4 4L8 20H4zM14 6l4 4',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1zM16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',target:'M21 12a9 9 0 1 1-9-9M17 12a5 5 0 1 1-5-5M12 12l9-9M17 3h4v4',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6zM8 12l3 3 5-6',up:'m6 14 6-6 6 6',down:'m6 10 6 6 6-6',copy:'M8 8h13v13H8zM16 8V3H3v13h5',trophy:'M7 3h10v6a5 5 0 0 1-10 0zM7 5H3v3a4 4 0 0 0 4 4M17 5h4v3a4 4 0 0 1-4 4M12 14v7M7 21h10',skip:'m4 5 11 7-11 7zM19 5v14',note:'M5 3h14v18H5zM8 8h8M8 12h8M8 16h5',back:'M20 12H4m6-6-6 6 6 6',bolt:'m13 2-9 12h7l-1 8 10-13h-7z'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.dumbbell}"/></svg>`;
const escapeRaw=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tr=text=>SetwerkI18n.text(text,state.language);
const localizeHTML=markup=>SetwerkI18n.html(markup,state.language);
const esc=value=>'\uE000'+escapeRaw(String(value??'').replace(/[\uE000\uE001]/g,''))+'\uE001';
const exName=ex=>state.language==='en'&&!ex.custom?(GYM_EXERCISES_EN[ex.id]?.name||ex.name):ex.name;
const itemName=it=>{const ex=exBy(it.exerciseId);return ex?exName(ex):it.exerciseName;};
const workoutName=w=>w.cardio&&w.name===w.cardio.type?tr(w.name):w.spontaneous&&w.name==='Spontantraining'?tr(w.name):w.name;
const instructionsFor=ex=>state.language==='en'&&!ex.custom?(GYM_EXERCISES_EN[ex.id]?.instructions||ex.instructions):ex.instructions;

const fmt=(n,d=1)=>Number(n||0).toLocaleString(state.language==='en'?'en-GB':'de-AT',{maximumFractionDigits:d});
const time=s=>`${Math.floor(Math.max(0,s)/60)}:${String(Math.floor(Math.max(0,s)%60)).padStart(2,'0')}`;
const dateLabel=(d,opts={day:'numeric',month:'long',year:'numeric'})=>new Date(d+'T12:00:00').toLocaleDateString(state.language==='en'?'en-GB':'de-AT',opts);
const categoryClass=x=>x.toLowerCase();
const badge=x=>`<span class="badge ${categoryClass(x)}">${esc(tr(x))}</span>`;
const btn=(label,action,cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const ib=(name,label,action,extra='',cls='')=>`<button type="button" class="icon-btn ${cls}" aria-label="${label}" title="${label}" data-action="${action}" ${extra}>${icon(name)}</button>`;
const allExercises=()=>[...GYM_EXERCISES,...state.customExercises];
const exBy=id=>allExercises().find(e=>e.id===id);
const options=(values,current,placeholder='')=>(placeholder?`<option value="">${placeholder}</option>`:'')+values.map(x=>`<option value="${esc(x)}" ${x===current?'selected':''}>${esc(x==='Ausdauer'?'Cardio':tr(x))}</option>`).join('');
function toast(text){$('#toast').textContent=tr(text);$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function save(){if(storageFault){showStorageError();return false;}try{const raw=JSON.stringify(state);if(window.AndroidGym){if(!AndroidGym.writeState(raw))throw Error('Speichern fehlgeschlagen');}else if(window.SetwerkCloud)SetwerkCloud.saveLocal(state);else localStorage.setItem(KEY,raw);writeFault=false;$('#storage-error')?.remove();return true;}catch(e){writeFault=true;showStorageError();return false;}}
function showStorageError(){if($('#storage-error'))return;const div=document.createElement('div');div.id='storage-error';div.className='storage-error';div.setAttribute('role','alert');div.textContent=tr(storageFault?'Deine gespeicherten Daten konnten nicht gelesen werden. Es wird nichts überschrieben. Bitte die App neu öffnen.':'Änderungen konnten nicht dauerhaft gespeichert werden. Bitte die App geöffnet lassen und Speicherplatz prüfen.');document.body.append(div);}
function persistDraft(){if(draft)state.draft=draft;else delete state.draft;save();}
function closeModal(){if($('#modal').open)$('#modal').close();$('#modal').innerHTML=localizeHTML('');modalKind='';}
function openModal(title,body,kind='generic'){lastFocus=document.activeElement?.id||'';const m=$('#modal');m.innerHTML=localizeHTML(`<div class="modal-head"><h2>${title}</h2>${ib('close','Schließen','close-modal')}</div><div class="modal-body">${body}</div>`);modalKind=kind;if(!m.open)m.showModal();}
function errorDisplay(err){toast(err.message||'Das hat nicht geklappt. Bitte nochmals versuchen.');}
const navs=[['home','home','Übersicht'],['templates','dumbbell','Vorlagen'],['exercises','book','Übungen'],['calendar','calendar','Kalender'],['progress','chart','Fortschritt']];
function languageToggle(){return `<button type="button" class="language-toggle" data-action="toggle-language" role="switch" aria-checked="${state.language==='en'}" aria-label="${state.language==='en'?'Language: English. Switch to German.':'Sprache: Deutsch. Zu Englisch wechseln.'}"><span aria-hidden="true" class="${state.language==='de'?'selected':''}">DE</span><span class="language-track" aria-hidden="true"><i></i></span><span aria-hidden="true" class="${state.language==='en'?'selected':''}">EN</span></button>`;}
function shell(body){return `<div class="app-shell"><aside class="sidebar"><button class="brand" data-action="nav" data-route="home"><span class="brand-mark">${icon('dumbbell')}</span>setwerk<span style="color:var(--accent)">.</span></button><nav class="nav" aria-label="Hauptnavigation">${navs.map(([r,i,l])=>`<button class="${route===r?'active':''}" data-action="nav" data-route="${r}">${icon(i)}${l}</button>`).join('')}</nav><div class="account-control sidebar-account"><button type="button" class="sidebar-auth-button" data-auth-open>Anmelden</button></div></aside><div class="app-content"><header class="app-topbar"><button class="brand topbar-brand" data-action="nav" data-route="home"><span class="brand-mark">${icon('dumbbell')}</span>setwerk.</button><div class="topbar-controls"><div class="account-control mobile-account"><button type="button" class="language-mini" data-auth-open data-auth-compact>Anmelden</button></div>${languageToggle()}</div></header><main class="main">${body}</main></div></div><nav class="bottom-nav" aria-label="Mobile Navigation">${navs.map(([r,i,l])=>`<button class="${route===r?'active':''}" data-action="nav" data-route="${r}">${icon(i)}<span>${l}</span></button>`).join('')}</nav>`;}

function heading(title,sub='',actions='',eyebrow='DEIN TRAINING'){return`<header class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${sub?`<p class="muted">${sub}</p>`:''}</div><div class="head-actions">${actions}</div></header>`;}
function empty(title,text,action='',glyph='dumbbell'){return`<div class="empty">${icon(glyph)}<h3>${title}</h3><p>${text}</p>${action}</div>`;}
function navigate(r){if(state.active&&r!=='focus'){openModal('Training läuft',`<p>Deine aktuelle Einheit ist noch offen.</p><div class="modal-actions">${btn('Training fortsetzen','resume','accent')}${btn('Training beenden oder erweitern','early-end','outline')}</div>`);return;}if((route==='editor'||route==='manual')&&draft){persistDraft();}closeModal();route=r;search='';limit=60;render();window.scrollTo(0,0);}
function sessionRow(s){return `<button class="session-row" data-action="session" data-id="${s.id}"><span class="date-block"><b>${new Date(s.date+'T12:00:00').getDate()}</b>${dateLabel(s.date,{month:'short'})}</span><span class="grow"><span class="title break">${esc(workoutName(s))}</span><span class="meta">${G.isActivity(s)?fmt(s.duration/60):Math.round(s.duration/60)} Min. · ${s.cardio?cardioInline(s.cardio):G.isActivity(s)?esc(s.sport||s.name):s.items.length+' Übungen'+(s.items.length?' · '+G.doneCount(s)+' Sätze':'')}</span></span>${badge(s.category)}${icon('chevron')}</button>`;}
function sortedSessions(){return [...state.sessions].sort((a,b)=>b.date.localeCompare(a.date)||(b.endedAt||0)-(a.endedAt||0));}
function home(){const start=G.weekStart(),week=state.sessions.filter(s=>s.date>=start&&s.date<=G.localDate()),days=Array.from({length:7},(_,i)=>{const d=new Date(start+'T12:00:00');d.setDate(d.getDate()+i);return G.localDate(d);});return `<header class="page-head home-welcome" data-welcome><div class="welcome-copy"><div class="eyebrow welcome-greeting" data-welcome-greeting></div><h1 data-welcome-message></h1><p class="muted">${dateLabel(G.localDate(),{weekday:'long',day:'numeric',month:'long'})}</p></div><div class="head-actions">${ib('target','Ziele und Erinnerungen','goals')}</div></header>`+`<div class="home-grid"><section class="start-card"><div class="eyebrow">FOCUS MODE</div><h2>Ein Satz nach<br>dem anderen.</h2><p>Mit Plan oder ganz spontan starten.</p>${btn(icon('play')+'Training starten','start-select','accent')}<div class="corner-icon">${icon('dumbbell')}</div></section><section class="goal-card"><div class="topline"><span class="eyebrow">DEINE WOCHE</span>${icon('target')}</div><div class="goal-num">${week.length} <span>/ ${state.goals.weekly}</span></div><small class="goal-desc">${week.length>=state.goals.weekly?'Wochenziel erreicht. Stark!':'abgeschlossene Einheiten'}</small><div class="week-bars">${days.map((d,i)=>`<span class="${week.some(s=>s.date===d)?'hit':''}"><i></i>${(state.language==='en'?['M','T','W','T','F','S','S']:['M','D','M','D','F','S','S'])[i]}</span>`).join('')}</div></section></div><div class="action-grid">${[['plus','Template erstellen','Deinen Trainingsplan zusammenstellen.','new-template'],['book','Übungsdatenbank',`${allExercises().length} Übungen. Deine Werte im Blick.`,'nav-exercises'],['calendar','Kalender','Alle Einheiten an einem Ort.','nav-calendar'],['note','Manuell aufzeichnen','Vergangene Einheiten ergänzen.','manual-new']].map(([i,t,s,a])=>`<button class="action-card" data-action="${a}"><span class="tile-icon">${icon(i)}</span><strong>${t}</strong><small>${s}</small></button>`).join('')}</div>${state.draft?`<div class="note row between" style="margin-bottom:24px"><span>Ein ungespeicherter Entwurf ist vorhanden.</span>${btn('Entwurf öffnen','resume-draft','outline')}</div>`:''}<div class="section-title"><h2>Deine letzten Einheiten</h2>${btn('Alle ansehen','nav-calendar','ghost')}</div><div class="stack">${state.sessions.length?sortedSessions().slice(0,3).map(sessionRow).join(''):empty('Hier beginnt dein Fortschritt.','Erstelle deine erste Vorlage oder trage ein vergangenes Training ein.',btn('Erste Vorlage erstellen','new-template','outline'))}</div>`;}
function templates(selectMode=false){return heading(selectMode?'Los geht’s.':'Deine Vorlagen.',selectMode?'Wähle deinen Plan für heute.':`${state.templates.length} Trainingsvorlagen`,btn(icon('plus')+'Vorlage erstellen','new-template')+btn('Workout importieren','import-workout','outline'),'TRAININGSPLAN')+(selectMode?`<button class="spontaneous-card" data-action="start-spontaneous"><span class="tile-icon">${icon('bolt')}</span><span class="grow"><strong>Spontantraining starten</strong><small>Ohne Vorlage beginnen. Übungen während des Trainings wählen.</small></span>${icon('play')}</button>`:'')+(state.templates.length?`<div class="template-grid">${state.templates.map(t=>`<article class="template-card"><div class="row between">${badge(t.category)}<span class="meta">${G.isActivity(t)?fmt(t.durationMinutes)+' Min.':t.items.reduce((n,x)=>n+x.sets.length,0)+' Sätze'}</span></div><h2 class="break">${esc(t.name)}</h2><div class="meta">${G.isActivity(t)?t.cardio?cardioInline(t.cardio):esc(t.sport||t.name):t.items.length+' Übungen · '+fmt(t.items.reduce((n,x)=>n+x.sets.length*x.rest,0)/60,0)+' Min. geplante Pausen'}</div><ul>${t.items.slice(0,4).map(it=>`<li>${esc(itemName(it))}</li>`).join('')}${t.items.length>4?`<li>+ ${t.items.length-4} weitere</li>`:''}</ul><footer>${btn(icon('play')+'Starten','start-template','',`data-id="${t.id}"`)}${ib('edit','Vorlage bearbeiten','edit-template',`data-id="${t.id}"`)}${btn('Teilen','export-template','ghost',`data-id="${t.id}"`)}${ib('copy','Vorlage duplizieren','copy-template',`data-id="${t.id}"`)}${ib('trash','Vorlage löschen','delete-template',`data-id="${t.id}"`,'danger')}</footer></article>`).join('')}</div>`:empty('Dein erster Trainingsplan','Füge Übungen hinzu. Drei Sätze und zwei Minuten Pause sind bereits voreingestellt.',btn(icon('plus')+'Vorlage erstellen','new-template','accent')));}
function newDraft(mode='template',session=null){if(draft&&state.draft&&route!=='editor'&&route!=='manual'){openModal('Entwurf fortsetzen?',`<p>Du hast bereits einen Entwurf. Möchtest du daran weiterarbeiten?</p><div class="modal-actions">${btn('Entwurf fortsetzen','resume-draft','accent')}${btn('Neuen Entwurf beginnen','replace-draft','outline',`data-mode="${mode}"`)}</div>`);return;}createDraft(mode,session);}
function createDraft(mode='template',session=null){draft=session?{...G.clone(session),mode:'manual',editId:session.id,durationMinutes:G.isActivity(session)?Math.round(session.duration/6)/10:Math.round(session.duration/60),items:session.items.map(it=>({...G.clone(it),sets:it.sets.map(s=>({...s,done:false}))}))}:{id:G.uid(),name:'',category:'Kraft',date:selectedDate,durationMinutes:60,notes:'',items:[],mode};manualMonth=draft.date?.slice(0,7)||G.localDate().slice(0,7);persistDraft();route=mode==='template'?'editor':'manual';closeModal();render();window.scrollTo(0,0);}
function editTemplate(id){draft={...G.clone(state.templates.find(t=>t.id===id)),mode:'template'};draft.durationMinutes=draft.durationMinutes||60;persistDraft();route='editor';closeModal();render();}
function fieldsForSet(s,it,i,k,context='draft'){const attr=name=>`data-context="${context}" data-item="${i}" data-set="${k}" data-field="${name}"`;const disabled=context==='active'&&(s.done||s.skipped)?'disabled':'';return`<tr class="${s.done?'done-row':''}"><td class="num">${s.done?icon('check'):k+1}</td><td><select aria-label="Satzart ${k+1}" class="set-type" ${attr('type')} ${disabled}>${[['normal','Arbeitssatz'],['warmup','Aufwärmen'],['drop','Dropsatz']].map(([v,l])=>`<option value="${v}" ${s.type===v?'selected':''}>${l}</option>`).join('')}</select></td>${it.kind==='reps'?`<td><input aria-label="Wiederholungen Satz ${k+1}" type="number" min="1" step="1" value="${s.reps}" ${attr('reps')} ${disabled}></td>`:`<td><input aria-label="Dauer in Sekunden Satz ${k+1}" type="number" min="0" step="1" value="${s.seconds}" ${attr('seconds')} ${disabled}></td>`}<td><input aria-label="Gewicht in Kilogramm Satz ${k+1}" type="number" min="0" step="0.25" value="${s.weight}" ${attr('weight')} ${disabled}></td>${it.kind==='distance'?`<td><input aria-label="Strecke in Metern Satz ${k+1}" type="number" min="0" step="1" value="${s.distance}" ${attr('distance')} ${disabled}></td>`:''}<td class="remove-col">${disabled?`<span class="locked">${s.skipped?'–':'✓'}</span>`:ib('close','Satz entfernen','remove-set',`data-context="${context}" data-item="${i}" data-set="${k}"`)}</td></tr>`;}
function itemEditor(it,i,context='draft'){const read=context==='active';const attr=f=>`data-context="${context}" data-item="${i}" data-field="${f}"`;return`<article class="exercise-edit"><div class="exercise-edit-header"><div class="grow"><h3>${esc(itemName(it))}</h3><div class="meta">${it.kind==='reps'?'Wiederholungen & Gewicht':it.kind==='time'?'Dauer':'Dauer & Strecke'}</div></div><div class="reorder">${!read?ib('up','Übung nach oben','move-item',`data-item="${i}" data-dir="-1"`)+ib('down','Übung nach unten','move-item',`data-item="${i}" data-dir="1"`)+ib('trash','Übung entfernen','remove-item',`data-item="${i}"`,'danger'):''}</div></div><div class="exercise-edit-body"><div class="set-scroll"><table class="set-table"><thead><tr><th>Satz</th><th>Art</th><th>${it.kind==='reps'?'Wdh.':'Dauer (s)'}</th><th>kg</th>${it.kind==='distance'?'<th>Strecke (m)</th>':''}<th></th></tr></thead><tbody>${it.sets.map((s,k)=>fieldsForSet(s,it,i,k,context)).join('')}</tbody></table></div>${btn(icon('plus')+'Satz hinzufügen','add-set','ghost',`data-context="${context}" data-item="${i}"`)}<div class="exercise-edit-controls"><label>Pause (Sekunden)<input type="number" min="0" max="3600" step="5" value="${it.rest}" ${attr('rest')}></label><label>Übungsnotiz<input value="${esc(it.notes)}" placeholder="z. B. Sitzhöhe 4" ${attr('notes')}></label></div><details><summary>Anstrengung je Satz · RPE / RIR</summary><p class="field-help">RPE: subjektive Anstrengung von 1 bis 10. RIR: geschätzte verbleibende Wiederholungen von 0 bis 10. Beide Angaben sind optional.</p><div class="set-scroll"><table class="set-table"><thead><tr><th>Satz</th><th>RPE</th><th>RIR</th></tr></thead><tbody>${it.sets.map((s,k)=>`<tr><td>${k+1}</td><td><input aria-label="RPE Satz ${k+1}" type="number" min="1" max="10" step="0.5" value="${s.rpe}" data-context="${context}" data-item="${i}" data-set="${k}" data-field="rpe"></td><td><input aria-label="RIR Satz ${k+1}" type="number" min="0" max="10" step="1" value="${s.rir}" data-context="${context}" data-item="${i}" data-set="${k}" data-field="rir"></td></tr>`).join('')}</tbody></table></div></details></div></article>`;}
function editor(manual=false){if(!draft)return home();if(draft.category==='Ausdauer')return cardioEditor(manual);const strength=['Kraft','Kraft-Ausdauer'].includes(draft.category);const head=heading(manual?(draft.editId?'Einheit bearbeiten.':'Training nachtragen.'):'Deine Vorlage.',manual?'Wähle den Tag und dokumentiere dein Training.':'Dein Plan, bereit für den nächsten Besuch.',ib('back','Zurück zur Übersicht','nav',`data-route="${manual?'calendar':'templates'}"`),manual?'MANUELLE AUFZEICHNUNG':'TRAININGSPLAN');return head+`<form id="editor-form" novalidate>${manual?`<div class="card manual-top"><div class="manual-calendar compact-calendar">${calendarWidget(manualMonth,draft.date,'manual')}</div><div class="${strength?'grid3':'grid2'}"><label>Datum<input type="date" value="${draft.date}" max="${G.localDate()}" data-draft="date" required></label><label>Dauer (Minuten)<input type="number" min="1" step="1" value="${draft.durationMinutes}" data-draft="durationMinutes" required></label>${strength?`<label>Vorlage übernehmen<select id="manual-template"><option value="">Ohne Vorlage</option>${state.templates.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label>`:''}</div></div>`:''}<div class="card grid2"><label>${draft.category==='Ballsport'?'Sportart':manual?'Name der Einheit':'Name der Vorlage'}<input id="draft-name" value="${esc(draft.name)}" data-draft="name" maxlength="100" placeholder="${draft.category==='Ballsport'?'z. B. Fußballtraining':manual?'z. B. Fußballtraining':'z. B. Oberkörper A'}" required></label><label>Trainingsart<select data-draft="category">${options(G.CATEGORIES,draft.category)}</select></label>${!manual&&draft.category==='Ballsport'?`<label>Dauer (Minuten)<input type="number" min="0.1" step="0.1" value="${draft.durationMinutes||60}" data-draft="durationMinutes" required></label>`:''}<label style="grid-column:1/-1">Notizen<textarea data-draft="notes" placeholder="Optional">${esc(draft.notes)}</textarea></label></div>${strength?`<div class="section-title"><h2>Übungen <span class="muted">${draft.items.length}</span></h2>${btn(icon('plus')+'Übung hinzufügen','pick-exercise','outline',`data-target="draft"`)}</div>${draft.items.length?`<div class="stack">${draft.items.map((it,i)=>itemEditor(it,i)).join('')}</div><div class="note" style="margin-top:16px">Vor einem Dropsatz entfällt die Pause.</div>`:empty('Welche Übungen stehen an?',manual?'Du kannst auch eine Sporteinheit nur mit Name, Art und Dauer speichern.':'Wähle aus dem Katalog oder lege eigene Übungen an.',btn('Übung auswählen','pick-exercise','outline','data-target="draft"'))}`:''}<div class="save-bar">${btn('Entwurf verwerfen','discard-draft','ghost')}<button class="btn accent" type="submit">${icon('check')}${manual?'Einheit speichern':'Vorlage speichern'}</button></div></form>`;}
function ensureCardioForm(){
 if(draft.cardioForm)return;
 const c=draft.cardio,oldDistance=(draft.items||[]).reduce((n,it)=>n+it.sets.reduce((m,x)=>m+(+x.distance||0),0),0);
 const oldName=(draft.items||[]).map(it=>it.exerciseName).join(' ')+' '+draft.name;
 const inferred=/rad|bike|cycling|ergometer/i.test(oldName)?'Radfahren':/schwimm|swim/i.test(oldName)?'Schwimmen':/cross|elliptical/i.test(oldName)?'Crosstrainer':/ruder|rowing/i.test(oldName)?'Rudern':/seil|rope/i.test(oldName)?'Seilspringen':'Laufen';
 draft.cardioForm={type:c?.type||inferred,other:c?.other||'',mode:c?.mode||'classic',modeName:c?.modeName||'',distanceKm:c?.distanceMeters!=null?c.distanceMeters/1000:oldDistance?oldDistance/1000:'',elevationM:c?.elevationMeters??'',count:c?.intervals?.count??6,workSeconds:c?.intervals?.workSeconds??60,restSeconds:c?.intervals?.restSeconds??60,intervalDistanceM:c?.intervals?.distanceMeters??''};
}
function updateIntervalDuration(){const f=draft.cardioForm;if(f?.mode!=='interval')return;const seconds=Number(f.count)*Number(f.workSeconds)+Math.max(0,Number(f.count)-1)*Number(f.restSeconds);draft.durationMinutes=Math.round(seconds/6)/10;const field=$('[data-draft="durationMinutes"]');if(field)field.value=draft.durationMinutes;}

function cardioFromDraft(){ensureCardioForm();const f=draft.cardioForm,c={type:f.type,other:f.type==='Sonstige'?f.other.trim():'',distanceMeters:!G.cardioHasDistance(f.type)||f.distanceKm===''?null:Math.round(Number(f.distanceKm)*1000),elevationMeters:!G.cardioHasElevation(f.type)||f.elevationM===''?null:Number(f.elevationM)};if(draft.mode==='template'||f.mode!=='classic'||draft.cardio?.mode){c.mode=f.mode;if(f.mode==='other')c.modeName=f.modeName.trim();if(f.mode==='interval')c.intervals={count:Number(f.count),workSeconds:Number(f.workSeconds),restSeconds:Number(f.restSeconds),distanceMeters:G.cardioHasDistance(f.type)&&f.intervalDistanceM!==''?Number(f.intervalDistanceM):null};}return c;}

function cardioModeName(c){return c.mode==='interval'?tr('Intervalltraining'):c.mode==='other'?c.modeName:tr('Klassisches Cardio');}
function cardioInline(c){return `${esc(c.type==='Sonstige'?c.other:tr(c.type))}${c.mode==='interval'?' · '+c.intervals.count+' × '+time(c.intervals.workSeconds):c.mode==='other'?' · '+esc(c.modeName):''}${c.distanceMeters!=null?' · '+fmt(c.distanceMeters/1000,3)+' km':''}${G.cardioHasElevation(c.type)&&c.elevationMeters!=null?' · '+fmt(c.elevationMeters,0)+' m ↑':''}`;}

function cardioSummary(c){return `<div class="cardio-summary"><h3>${esc(c.type==='Sonstige'?c.other:tr(c.type))}</h3>${c.mode?`<p class="meta">${esc(cardioModeName(c))}</p>`:''}<div class="detail-metrics">${c.distanceMeters!=null?`<div class="metric"><span class="mini-label">DISTANZ</span><strong>${fmt(c.distanceMeters/1000,3)} km</strong></div>`:''}${G.cardioHasElevation(c.type)&&c.elevationMeters!=null?`<div class="metric"><span class="mini-label">HÖHENMETER</span><strong>${fmt(c.elevationMeters,0)} m</strong></div>`:''}${c.mode==='interval'?`<div class="metric"><span class="mini-label">INTERVALLE</span><strong>${c.intervals.count} × ${time(c.intervals.workSeconds)}</strong><small>${time(c.intervals.restSeconds)} Pause${c.intervals.distanceMeters!=null?' · '+fmt(c.intervals.distanceMeters,0)+' m / Intervall':''}</small></div>`:''}</div></div>`;}

function cardioEditor(manual=false){ensureCardioForm();const c=draft.cardioForm;return heading(manual?(draft.editId?'Einheit bearbeiten.':'Training nachtragen.'):'Deine Vorlage.',manual?'Wähle den Tag und dokumentiere dein Training.':'Dein Plan, bereit für den nächsten Besuch.',ib('back','Zurück zur Übersicht','nav',`data-route="${manual?'calendar':'templates'}"`),manual?'MANUELLE AUFZEICHNUNG':'TRAININGSPLAN')+`<form id="editor-form" novalidate>${manual?`<div class="card manual-top"><div class="manual-calendar compact-calendar">${calendarWidget(manualMonth,draft.date,'manual')}</div><label>Datum<input type="date" value="${draft.date}" max="${G.localDate()}" data-draft="date" required></label></div>`:''}<div class="card inline-form cardio-form">${!manual?`<label>Name der Vorlage<input id="draft-name" value="${esc(draft.name)}" data-draft="name" maxlength="100" placeholder="z. B. Lauftraining" required></label>`:''}<div class="grid2"><label>Trainingsart<select data-draft="category">${options(G.CATEGORIES,draft.category)}</select></label><label>Cardio-Trainingsform<select data-cardio="mode">${[['classic','Klassisches Cardio'],['interval','Intervalltraining'],['other','Sonstiges']].map(([v,n])=>`<option value="${v}" ${c.mode===v?'selected':''}>${n}</option>`).join('')}</select></label></div>${c.mode==='other'?`<label>Name der Trainingsform<input data-cardio="modeName" value="${esc(c.modeName)}" maxlength="100" placeholder="z. B. Fahrtspiel" required></label>`:''}<label>Cardio-Art<select data-cardio="type">${options(G.CARDIO_TYPES,c.type)}</select></label>${c.type==='Sonstige'?`<label>Welche Aktivität?<input data-cardio="other" value="${esc(c.other)}" maxlength="100" placeholder="z. B. Wandern" required></label>`:''}${c.mode==='interval'?`<div class="grid2"><label>Anzahl Intervalle<input type="number" min="1" max="1000" step="1" data-cardio="count" value="${c.count}" required></label><label>Belastung je Intervall (Sekunden)<input type="number" min="1" max="86400" step="1" data-cardio="workSeconds" value="${c.workSeconds}" required></label><label>Pause zwischen Intervallen (Sekunden)<input type="number" min="0" max="3600" step="1" data-cardio="restSeconds" value="${c.restSeconds}" required></label>${G.cardioHasDistance(c.type)?`<label>Distanz je Intervall (m, optional)<input type="number" min="0" step="1" data-cardio="intervalDistanceM" value="${esc(c.intervalDistanceM)}"></label>`:''}</div><p class="field-help">Die geplante Dauer ergibt sich aus Belastungen und Pausen. Du kannst sie für Aufwärmen und Abkühlen anpassen.</p>`:''}<div class="grid2"><label>Dauer (Minuten)<input type="number" min="0.1" step="0.1" inputmode="decimal" value="${draft.durationMinutes}" data-draft="durationMinutes" required></label>${G.cardioHasDistance(c.type)?`<label>${manual&&c.mode==='classic'?'Distanz (km)':'Distanz (km, optional)'}<input type="number" min="0" step="0.001" inputmode="decimal" value="${esc(c.distanceKm)}" data-cardio="distanceKm" ${manual&&c.mode==='classic'?'required':''}></label>`:''}${G.cardioHasElevation(c.type)?`<label>Höhenmeter (optional)<input type="number" min="0" step="1" inputmode="numeric" value="${esc(c.elevationM)}" data-cardio="elevationM" placeholder="Optional"></label>`:''}</div><label>Notizen<textarea data-draft="notes" placeholder="Optional">${esc(draft.notes)}</textarea></label></div><div class="save-bar">${btn('Entwurf verwerfen','discard-draft','ghost')}<button class="btn accent" type="submit">${icon('check')}${manual?'Einheit speichern':'Vorlage speichern'}</button></div></form>`;}

function filteredExercises(q,m,e){const norm=x=>x.toLocaleLowerCase('de').normalize('NFD').replace(/[\u0300-\u036f]/g,'');return allExercises().filter(x=>(!q||norm(x.name+' '+exName(x)+' '+tr(x.muscle)+' '+x.muscle+' '+tr(x.equipment)+' '+x.equipment).includes(norm(q)))&&(!m||x.muscle===m)&&(!e||x.equipment===e));}
function recordText(record,kind){if(!record)return'Noch kein PR';if(kind==='reps')return record.weight>0?`${fmt(record.weight)} kg × ${record.reps}`:`${record.reps} Wdh.`;return kind==='distance'&&record.distance?`${fmt(record.distance,0)} m`:time(record.seconds);}
function exerciseRows(list,picker=false){return list.map(ex=>{const record=G.best(state.sessions,ex.id,ex.kind),hist=G.exerciseHistory(state.sessions,ex.id);return`<button class="exercise-row" data-action="${picker?'choose-exercise':'exercise'}" data-id="${ex.id}"><span class="exercise-index">${icon(ex.kind==='reps'?'dumbbell':'clock')}</span><span class="grow"><strong>${esc(exName(ex))}</strong><span class="meta">${esc(tr(ex.muscle))} · ${esc(tr(ex.equipment))}</span></span>${picker?icon('plus'):`<span class="record">${recordText(record,ex.kind)}<small>${hist.length?'Zuletzt '+dateLabel(hist[0].date,{day:'2-digit',month:'2-digit'}):'Noch nicht trainiert'}</small></span>`}</button>`;}).join('');}
function exercises(){const list=filteredExercises(search,muscle,equipment);return heading('Deine Übungen.',`${allExercises().length} Übungen. Dein Fortschritt bei jeder einzelnen.`,btn(icon('plus')+'Eigene Übung','custom-exercise'),'ÜBUNGSDATENBANK')+`<div class="filter-bar"><label class="search-wrap"><span class="sr-only">Übung suchen</span>${icon('search')}<input id="exercise-search" placeholder="Übung suchen …" value="${esc(search)}"></label><label><span class="sr-only">Muskelgruppe</span><select id="muscle-filter">${options([...new Set(allExercises().map(x=>x.muscle))].sort(),muscle,'Alle Muskelgruppen')}</select></label><label><span class="sr-only">Equipment</span><select id="equipment-filter">${options([...new Set(allExercises().map(x=>x.equipment))].sort(),equipment,'Jedes Equipment')}</select></label></div><div id="exercise-results">${exerciseResults(list)}</div>`;}
function exerciseResults(list){return`<div class="filter-count">${list.length} Übungen gefunden</div><div class="exercise-list">${exerciseRows(list.slice(0,limit))||empty('Keine passende Übung','Ändere die Suche oder lege eine eigene Übung an.')}</div>${list.length>limit?btn('Weitere Übungen anzeigen','more-exercises','outline load-more'):''}`;}
function openPicker(target){pickerTarget=target;pickerSearch='';pickerMuscle='';openModal('Übung hinzufügen',`<div class="filter-bar"><label class="search-wrap"><span class="sr-only">Übung suchen</span>${icon('search')}<input id="picker-search" placeholder="Übung suchen …"></label><label><span class="sr-only">Muskelgruppe</span><select id="picker-muscle">${options([...new Set(allExercises().map(x=>x.muscle))].sort(),'','Alle Muskelgruppen')}</select></label>${btn(icon('plus')+'Eigene Übung','custom-exercise','outline','data-return="picker"')}</div><div id="picker-results" class="exercise-list">${exerciseRows(allExercises(),true)}</div>`,'picker');}
function openCustom(back=false){openModal('Eigene Übung',`<form id="custom-form" class="inline-form"><label>Übungsname<input name="name" maxlength="100" required placeholder="Name deiner Übung"></label><div class="grid2"><label>Muskelgruppe<select name="muscle">${options([...new Set(GYM_EXERCISES.map(x=>x.muscle))],'Ganzkörper')}</select></label><label>Equipment<input name="equipment" maxlength="80" placeholder="z. B. Eigengewicht" required></label></div><label>Aufzeichnung<select name="kind"><option value="reps">Wiederholungen & Gewicht</option><option value="time">Dauer</option><option value="distance">Dauer & Strecke</option></select></label><label>Eigene Anleitung<textarea name="instructions" placeholder="Deine Hinweise zur Ausführung"></textarea></label><input name="back" type="hidden" value="${back?'picker':''}"><button class="btn accent" type="submit">Übung speichern</button></form>`,'custom');}
function chart(points,title,unit){title=tr(title);unit=tr(unit);if(!points.length)return empty('Noch keine Daten','Deine abgeschlossenen Einheiten erscheinen hier.','','chart');const vals=points.map(p=>p.value),max=Math.max(...vals,1),w=540,h=160,pad=35,span=w-pad*2,x=i=>points.length===1?w/2:pad+i*span/(points.length-1),y=v=>h-20-(v/max)*(h-40),poly=points.map((p,i)=>`${x(i)},${y(p.value)}`).join(' ');return`<svg class="chart" viewBox="0 0 ${w} ${h+30}" role="img" aria-label="${esc(tr(title))}"><line x1="${pad}" y1="${h-20}" x2="${w-pad}" y2="${h-20}" stroke="#dce3da"/><line x1="${pad}" y1="20" x2="${w-pad}" y2="20" stroke="#e9eee5" stroke-dasharray="3 5"/><text x="${pad}" y="12">${fmt(max)} ${unit}</text><polyline points="${poly}" fill="none" stroke="#5b833e" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${points.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.value)}" r="4.5" fill="#739d46"><title>${esc(p.label)}: ${fmt(p.value)} ${unit}</title></circle>${i===0||i===points.length-1?`<text x="${x(i)}" y="${h+9}" text-anchor="middle">${esc(p.short||p.label)}</text>`:''}`).join('')}</svg><details><summary>Werte als Tabelle</summary><table class="data-table"><thead><tr><th>Datum</th><th>${esc(tr(title))} (${unit})</th></tr></thead><tbody>${points.map(p=>`<tr><td>${esc(p.label)}</td><td>${fmt(p.value)}</td></tr>`).join('')}</tbody></table></details>`;}
function setText(s,it){return it.kind==='reps'?`${s.reps} Wdh. × ${fmt(s.weight)} kg`:`${time(s.seconds)}${it.kind==='distance'?' · '+fmt(s.distance,0)+' m':''}${s.weight?' · '+fmt(s.weight)+' kg':''}`;}
function exerciseDetail(id,metric=''){const ex=exBy(id);if(!ex)return;selectedExercise=id;const hist=G.exerciseHistory(state.sessions,id),pr=G.best(state.sessions,id,ex.kind),last=hist[0];metric=metric||(ex.kind==='reps'?(pr?.weight>0?'weight':'reps'):ex.kind==='time'?'seconds':'distance');const unit={weight:'kg',reps:'Wdh.',volume:'kg',seconds:'Min.',distance:'m'}[metric],metricTitle={weight:'Höchstes Arbeitsgewicht',reps:'Meiste Wiederholungen',volume:'Trainingsvolumen',seconds:'Längste Satzdauer',distance:'Weiteste Strecke'}[metric],points=hist.slice(0,12).reverse().map(w=>({label:dateLabel(w.date),short:dateLabel(w.date,{day:'2-digit',month:'2-digit'}),value:(()=>{const ss=w.items.filter(it=>it.exerciseId===id).flatMap(it=>it.sets.filter(s=>s.done&&s.type!=='warmup'));return metric==='volume'?ss.reduce((n,s)=>n+s.weight*s.reps,0):Math.max(...ss.map(s=>metric==='seconds'?s.seconds/60:s[metric]),0);})()}));openModal(esc(exName(ex)),`<div class="meta">${esc(tr(ex.muscle))} · ${esc(tr(ex.equipment))}</div><div class="detail-metrics"><div class="metric"><span class="mini-label">${ex.kind==='reps'?'BESTER SATZ':ex.kind==='time'?'LÄNGSTE DAUER':'WEITESTE STRECKE'}</span><strong>${recordText(pr,ex.kind)}</strong><small>${pr?dateLabel(pr.date):'Ohne Aufwärmsätze'}</small></div><div class="metric"><span class="mini-label">ZULETZT TRAINIERT</span><strong>${last?dateLabel(last.date,{day:'numeric',month:'short'}):'—'}</strong><small>${hist.length} Einheiten</small></div></div><h3>Ausführung</h3><ol class="guide">${(instructionsFor(ex)||[]).map(t=>`<li>${esc(t)}</li>`).join('')||'<li>Keine Anleitung hinterlegt.</li>'}</ol>${last?`<h3>Letzte Ausführung · ${esc(workoutName(last))}</h3>${last.items.filter(it=>it.exerciseId===id).map(it=>it.sets.filter(s=>s.done).map((s,i)=>`<div class="finished-set"><span class="num">${i+1}</span><strong>${setText(s,it)}</strong><span class="meta">${s.type==='warmup'?'Aufwärmen':s.type==='drop'?'Dropsatz':''}${s.rpe!==''?' · RPE '+s.rpe:''}${s.rir!==''?' · RIR '+s.rir:''}</span></div>`).join('')).join('')}<h3 style="margin-top:26px">Deine Entwicklung</h3><label>Messwert<select id="exercise-metric">${(ex.kind==='reps'?[['weight','Höchstes Arbeitsgewicht'],['reps','Meiste Wiederholungen'],['volume','Trainingsvolumen']]:ex.kind==='time'?[['seconds','Längste Satzdauer']]:[['distance','Weiteste Strecke'],['seconds','Längste Satzdauer']]).map(([value,label])=>`<option value="${value}" ${value===metric?'selected':''}>${label}</option>`).join('')}</select></label>${chart(points,metricTitle,unit)}`:'<div class="note">Dein erster abgeschlossener Satz legt die Basis für deine Fortschritte.</div>'}`,'exercise');}
function calendarWidget(month,selection,mode='calendar'){const [yr,mo]=month.split('-').map(Number),first=new Date(yr,mo-1,1,12),offset=(first.getDay()+6)%7,days=new Date(yr,mo,0,12).getDate(),cells=Array.from({length:offset},()=>'<span class="cal-day blank"></span>');for(let d=1;d<=days;d++){const key=`${month}-${String(d).padStart(2,'0')}`,ss=state.sessions.filter(s=>s.date===key),disabled=mode==='manual'&&key>G.localDate();cells.push(`<button type="button" class="cal-day ${key===G.localDate()?'today':''} ${key===selection?'selected':''}" aria-label="${dateLabel(key)}${ss.length?', '+ss.length+' Einheiten':''}" aria-pressed="${key===selection}" data-action="select-date" data-mode="${mode}" data-date="${key}" ${disabled?'disabled':''}><span>${d}</span><span class="cal-dots">${[...new Set(ss.map(s=>s.category))].map(c=>`<i class="dot-${categoryClass(c)}" title="${c}"></i>`).join('')}</span></button>`);}return`<div class="calendar-head">${ib('left','Vorheriger Monat','month',`data-mode="${mode}" data-dir="-1"`)}<h2>${first.toLocaleDateString(state.language==='en'?'en-GB':'de-AT',{month:'long',year:'numeric'})}</h2>${ib('chevron','Nächster Monat','month',`data-mode="${mode}" data-dir="1"`)}</div><div class="weekdays">${(state.language==='en'?['Mon','Tue','Wed','Thu','Fri','Sat','Sun']:['Mo','Di','Mi','Do','Fr','Sa','So']).map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${cells.join('')}</div>`;}
function calendarPage(){const todaySessions=sortedSessions().filter(s=>s.date===selectedDate);return heading('Dein Kalender.','Jede Einheit zählt.',btn(icon('plus')+'Nachtragen','manual-new'),'TRAININGSVERLAUF')+`<div class="calendar-layout"><section class="card">${calendarWidget(calMonth,selectedDate)}<div class="legend">${G.CATEGORIES.map(c=>`<span><i class="dot-${categoryClass(c)}"></i>${c}</span>`).join('')}</div></section><section class="day-sessions"><h2>${dateLabel(selectedDate,{weekday:'short',day:'numeric',month:'long'})}</h2><div class="stack">${todaySessions.map(sessionRow).join('')||empty('Kein Training eingetragen','Hier erscheinen deine Einheiten für diesen Tag.',selectedDate<=G.localDate()?btn('Einheit nachtragen','manual-new','outline'):'','calendar')}</div></section></div><div class="section-title" style="margin-top:34px"><h2>Alle Einheiten</h2><span class="meta">${state.sessions.length} insgesamt</span></div><div class="stack">${sortedSessions().slice(0,30).map(sessionRow).join('')||'<p class="muted">Dein Trainingsverlauf ist noch leer.</p>'}</div>${state.sessions.length>30?'<p class="meta">Die letzten 30 Einheiten werden angezeigt. Ältere Einheiten findest du über den Kalender.</p>':''}`;}
function progress(){const ss=sortedSessions(),volume=ss.reduce((n,s)=>n+G.volume(s),0),mins=ss.reduce((n,s)=>n+s.duration/60,0),points=ss.slice(0,12).reverse().map(s=>({label:dateLabel(s.date)+' · '+s.name,short:dateLabel(s.date,{day:'2-digit',month:'2-digit'}),value:G.volume(s)})),durationPoints=ss.slice(0,12).reverse().map(s=>({label:dateLabel(s.date)+' · '+s.name,short:dateLabel(s.date,{day:'2-digit',month:'2-digit'}),value:Math.round(s.duration/60)}));const records=allExercises().map(ex=>({ex,pr:G.best(ss,ex.id,ex.kind)})).filter(x=>x.pr);return heading('Dein Fortschritt.','Was du aufzeichnest, wird sichtbar.',btn(icon('target')+'Ziele','goals','outline'),'DEINE ENTWICKLUNG')+`<div class="stat-cards"><div class="card"><small>Einheiten</small><strong>${ss.length}</strong></div><div class="card"><small>Trainingszeit</small><strong>${fmt(mins/60)} h</strong></div><div class="card"><small>Volumen</small><strong>${fmt(volume/1000)} t</strong></div></div><div class="summary-columns"><div class="card chart-card"><h2>Trainingsvolumen</h2><p class="meta">Gewicht × Wiederholungen · ohne Aufwärmsätze</p>${chart(points,'Volumen','kg')}</div><div class="card chart-card"><h2>Dauer pro Einheit</h2><p class="meta">Deine letzten zwölf Trainingseinheiten</p>${chart(durationPoints,'Trainingsdauer','Min.')}</div></div><div class="section-title" style="margin-top:32px"><h2>Deine Bestleistungen</h2><span class="meta">${records.length} Übungen</span></div><div class="exercise-list">${records.length?exerciseRows(records.map(x=>x.ex)):empty('Deine Rekorde warten auf dich.','Abgeschlossene Arbeitssätze werden automatisch ausgewertet.','','trophy')}</div><p class="meta" style="margin-top:18px">Gewichtsrekorde vergleichen zuerst das Gewicht, dann die Wiederholungen. Bei Körpergewichtsübungen wird Zusatzgewicht erfasst. Zeit- und Streckenrekorde vergleichen die längste Dauer bzw. weiteste Strecke, nicht das Tempo.</p>`;}
function sessionDetail(id){const s=state.sessions.find(s=>s.id===id);if(!s)return;viewSession=id;openModal(esc(workoutName(s)),`<div class="row between">${badge(s.category)}<span class="meta">${dateLabel(s.date)}</span></div><div class="detail-metrics"><div class="metric"><span class="mini-label">DAUER</span><strong>${G.isActivity(s)?fmt(s.duration/60):Math.round(s.duration/60)} Min.</strong></div>${G.isActivity(s)?'':`<div class="metric"><span class="mini-label">SÄTZE</span><strong>${G.doneCount(s)}</strong></div>`}</div>${s.cardio?cardioSummary(s.cardio):''}${feedbackSummary(s)}${s.notes?`<div class="note break">${esc(s.notes)}</div>`:''}${s.items.map(it=>`<h3 style="margin:24px 0 10px">${esc(itemName(it))}</h3>${it.notes?`<p class="meta break">${esc(it.notes)}</p>`:''}${it.sets.map((set,i)=>`<div class="finished-set"><span class="num">${i+1}</span><strong>${setText(set,it)}</strong><span class="meta">${set.type==='warmup'?'Aufwärmen':set.type==='drop'?'Dropsatz':''}${set.rpe!==''?' · RPE '+set.rpe:''}${set.rir!==''?' · RIR '+set.rir:''}</span></div>`).join('')}`).join('')}<div class="modal-actions">${btn('Einheit bearbeiten','edit-session','outline',`data-id="${id}"`)}${btn('Workout teilen','export-session','outline',`data-id="${id}"`)}${btn('Trainingsgefühl bearbeiten','edit-feedback','outline',`data-id="${id}"`)}${s.items.length&&!s.cardio?btn(icon('play')+'Training wiederholen','repeat-session','accent',`data-id="${id}"`)+btn('Als Vorlage übernehmen','session-template','outline',`data-id="${id}"`):''}${btn('Einheit löschen','delete-session','danger',`data-id="${id}"`)}</div>`,'session');}
function previousSet(it,k){const h=G.exerciseHistory(state.sessions,it.exerciseId);if(!h.length)return null;const sets=h[0].items.filter(x=>x.exerciseId===it.exerciseId).flatMap(x=>x.sets.filter(s=>s.done));return sets[k]||sets.at(-1);}
function activityFocus(a){return `<div class="focus-shell"><header class="focus-top"><div class="focus-title"><strong>FOCUS MODE</strong>${esc(workoutName(a))}</div><div class="focus-top-actions">${btn('Beenden','activity-finish')}${languageToggle()}</div></header><main class="focus-main"><div class="eyebrow">${esc(tr(a.category))}</div><h1>${esc(a.sport||a.name)}</h1><div id="activity-clock" class="rest-clock">${time(Math.floor((Date.now()-a.startedAt)/1000))}</div><p class="meta">Geplant: ${fmt(a.durationMinutes)} Min.</p>${a.cardio?cardioSummary(a.cardio):''}${a.notes?`<p class="focus-note break">${esc(a.notes)}</p>`:''}<p class="focus-last">Dein Training läuft lokal. Nach dem Abschluss werden die Daten gespeichert.</p>${btn(icon('check')+'Training abschließen','activity-finish','accent focus-complete')}${btn('Training verwerfen','discard-active','ghost')}</main></div>`;}
function openActivityFinish(){const a=state.active;if(!a)return;const c=a.cardio,minutes=a.actualDurationSeconds?a.actualDurationSeconds/60:Math.max(0.1,Math.round((Date.now()-a.startedAt)/6000)/10);openModal('Training abschließen',`<form id="activity-finish-form" class="inline-form"><label>Dauer (Minuten)<input name="minutes" type="number" min="0.1" step="0.1" value="${minutes}" required></label>${c&&G.cardioHasDistance(c.type)?`<label>Erreichte Distanz (km, optional)<input name="distanceKm" type="number" min="0" step="0.001" value="${a.actualDurationSeconds&&c.distanceMeters!=null?c.distanceMeters/1000:''}"></label>`:''}${c&&G.cardioHasElevation(c.type)?`<label>Höhenmeter (optional)<input name="elevationM" type="number" min="0" step="1" value="${a.actualDurationSeconds&&c.elevationMeters!=null?c.elevationMeters:''}"></label>`:''}<label>Notizen<textarea name="notes">${esc(a.notes)}</textarea></label><button class="btn accent" type="submit">Weiter zum Trainingsgefühl</button>${btn('Zum laufenden Training zurück','resume','outline')}</form>`,'activity-finish');}
function focus(){
 const a=state.active;if(!a){route='home';return shell(home());}if(G.isActivity(a))return activityFocus(a);
 const p=G.next(a),total=a.items.reduce((n,it)=>n+it.sets.filter(s=>!s.skipped).length,0),done=G.doneCount(a);let body;
 if(p){
  const it=a.items[p.i],set=it.sets[p.s],n=G.schedule(a.items).find(q=>q.i!==p.i&&!a.items[q.i].sets[q.s].done&&!a.items[q.i].sets[q.s].skipped),nextEx=n?a.items[n.i]:null,last=previousSet(it,p.s),type=set.type==='warmup'?' · Aufwärmsatz':set.type==='drop'?' · Dropsatz':'';
  body=`<div class="eyebrow">ÜBUNG ${p.i+1} / ${a.items.length}${type}</div><div class="focus-exercise-title"><h1>${esc(itemName(it))}</h1>${ib('edit','Übung wechseln','replace-exercise','','exercise-pencil')}</div>
  <div class="set-dots" aria-label="Satz ${p.s+1} von ${it.sets.length}">${it.sets.map((st,k)=>`<span class="set-dot ${st.done?'done':k===p.s?'current':''}">${st.done?icon('check'):k+1}</span>`).join('')}</div>
  <button class="focus-details" data-action="focus-settings">${it.sets.length} Sätze · ${time(it.rest)} Pause ${icon('edit')}</button>
  <div class="focus-values">
   <button class="focus-value" data-action="edit-value" data-field="${it.kind==='reps'?'reps':'seconds'}" aria-label="${it.kind==='reps'?'Wiederholungen ändern':'Dauer ändern'}"><strong id="focus-primary">${it.kind==='reps'?set.reps:time(set.seconds)}</strong><span>${it.kind==='reps'?'WIEDERHOLUNGEN':'DAUER · MIN:SEK'} ${icon('edit')}</span></button>
   <button class="focus-value" data-action="edit-value" data-field="${it.kind==='distance'?'distance':'weight'}" aria-label="${it.kind==='distance'?'Strecke ändern':'Gewicht ändern'}"><strong>${fmt(it.kind==='distance'?set.distance:set.weight,it.kind==='distance'?0:1)}</strong><span>${it.kind==='distance'?'METER':'KILOGRAMM'} ${icon('edit')}</span></button>
  </div>
  ${it.kind==='distance'&&set.weight?`<button class="focus-details" data-action="edit-value" data-field="weight">${fmt(set.weight)} kg Zusatzgewicht ${icon('edit')}</button>`:''}
  ${it.kind!=='reps'?btn(icon('clock')+(a.timer?'Stoppuhr stoppen':'Stoppuhr starten'),'exercise-timer','outline'):''}
  <p class="focus-last">${last?'Zuletzt: '+setText(last,it):'Dein erster Eintrag für diese Übung'}</p>${it.notes?`<p class="focus-note break">${icon('note')} ${esc(it.notes)}</p>`:''}
  ${btn(icon('check')+'Nächster Satz','complete-set','accent focus-complete')}
  <div class="next-card"><div><small>${nextEx?'Nächste Übung':'Danach'}</small><strong>${nextEx?esc(itemName(nextEx)):'Training abschließen oder Übungen ergänzen'}</strong></div>${icon(nextEx?'dumbbell':'check')}</div>`;
 }else if(!done){
  body=`<div class="spontaneous-symbol">${icon('bolt')}</div><div class="eyebrow">SPONTANTRAINING</div><h1>Dein Training.<br>Dein Rhythmus.</h1><p class="focus-last">Die Einheit läuft. Wähle deine erste Übung, wenn du bereit bist.</p>${btn(icon('plus')+'Erste Übung wählen','extend-final','accent focus-complete')}`;
 }else{
  body=`<div class="finish-icon">${icon('check')}</div><div class="eyebrow">${a.spontaneous?'DEINE EINHEIT':'DEIN PLAN IST GESCHAFFT'}</div><h1>Stark gemacht.</h1><p class="focus-last">${done} Sätze abgeschlossen.</p><div class="stack" style="max-width:440px;margin:30px auto">${btn('Training beenden','save-active','accent')}${btn(icon('plus')+'Weitere Übungen aufzeichnen','extend-final','outline')}${btn('Notizen & Anstrengung ergänzen','focus-settings','ghost')}</div>`;
 }
 const remaining=a.rest?Math.max(0,Math.ceil((a.rest.until-Date.now())/1000)):0;
 return `<div class="focus-shell"><header class="focus-top"><div class="focus-title"><strong>FOCUS MODE</strong>${esc(workoutName(a))}</div><div class="focus-top-actions">${btn('Beenden','early-end')}${languageToggle()}</div></header><main class="focus-main">${body}</main><footer class="focus-footer">${done} von ${total} Sätzen abgeschlossen</footer></div>${remaining>0?`<div class="rest-overlay" role="region" aria-label="Satzpause"><div class="eyebrow">DURCHATMEN.</div><h2>Deine Pause</h2><div id="rest-clock" class="rest-clock" aria-live="off">${time(remaining)}</div><div class="rest-progress"><i id="rest-bar" style="width:${remaining/a.rest.total*100}%"></i></div><p>${p?'Gleich weiter mit '+esc(itemName(a.items[p.i])):'Alle geplanten Sätze sind geschafft.'}</p>${btn(icon('skip')+'Pause überspringen','skip-rest')}</div>`:''}`;
}
function editValue(field){
 stopExerciseClock();const p=G.next(state.active);if(!p)return;const it=state.active.items[p.i],set=it.sets[p.s];
 const labels={reps:'Wiederholungen ändern',weight:'Gewicht ändern',seconds:'Dauer ändern',distance:'Strecke ändern'},units={reps:'Wiederholungen',weight:'Kilogramm',seconds:'Sekunden',distance:'Meter'};
 if(!labels[field])throw Error('Ungültiger Trainingswert.');
 openModal(labels[field],`<form id="value-form" class="inline-form"><input type="hidden" name="field" value="${field}"><label>${units[field]}<input id="quick-value" name="value" class="quick-value" type="number" inputmode="${field==='weight'?'decimal':'numeric'}" min="${field==='reps'?1:0}" step="${field==='weight'?0.25:1}" value="${set[field]}" required></label><label class="inline-check"><input type="checkbox" name="remaining">Für alle verbleibenden Sätze dieser Übung übernehmen</label><button class="btn accent" type="submit">Übernehmen</button></form>`,'value');
 $('#quick-value').focus();$('#quick-value').select();
}
function chooseExercise(ex){
 if(pickerTarget==='draft'){draft.items.push(G.item(ex));persistDraft();}
 else{const a=state.active;if(pickerTarget==='replace-active')G.replaceCurrentExercise(a,ex);else{if(pickerTarget==='extend-early')G.skipPending(a);a.items.push(G.item(ex));}a.rest=null;window.AndroidGym?.cancelRest();save();}
 closeModal();render('exercise');toast(pickerTarget==='replace-active'?'Übung gewechselt.':'Übung hinzugefügt.');
}
const MOODS=['Sehr schlecht','Eher schlecht','Neutral','Gut','Sehr gut'];
const EFFORTS=['Sehr leicht','Leicht','Passend','Anstrengend','Sehr anstrengend'];
function feedbackFields(value={}){return `<fieldset class="feedback-field"><legend>Wie fühlst du dich gerade?</legend><div class="rating-options">${MOODS.map((name,i)=>`<label class="rating-option"><input type="radio" name="mood" value="${i+1}" ${value.mood===i+1?'checked':''}><span class="rating-emoji" aria-hidden="true">${['😞','🙁','😐','🙂','😄'][i]}</span><span>${name}</span></label>`).join('')}</div></fieldset><fieldset class="feedback-field"><legend>Wie hast du das Training empfunden?</legend><div class="rating-options effort-options">${EFFORTS.map((name,i)=>`<label class="rating-option"><input type="radio" name="effort" value="${i+1}" ${value.effort===i+1?'checked':''}><span class="effort-number">${i+1}</span><span>${name}</span></label>`).join('')}</div></fieldset><label>Persönliche Notiz<textarea name="feedbackNote" maxlength="2000" placeholder="Was möchtest du festhalten?">${esc(value.note||'')}</textarea></label>`;}
function openFeedback(id='active'){
 feedbackTarget=id;const session=id==='active'?state.active:state.sessions.find(s=>s.id===id);if(!session)return;
 if(id==='active'){stopExerciseClock();if(!G.isActivity(session)&&!G.doneCount(session))throw Error('Es wurde noch kein Satz abgeschlossen.');if(!session.finishedAt)session.finishedAt=Date.now();session.rest=null;session.feedbackStage=true;window.AndroidGym?.cancelRest();save();}
 feedbackDraft=G.clone(session.feedback||{mood:null,effort:null,note:''});
 openModal('Dein Trainingsgefühl',`<form id="feedback-form" class="inline-form"><p class="meta">Ein kurzer Check-in nach dem Training. Alle Angaben sind optional.</p>${feedbackFields(feedbackDraft)}<div class="modal-actions"><button class="btn accent" type="submit">${id==='active'?'Training speichern':'Feedback speichern'}</button>${id==='active'?btn('Ohne Feedback speichern','skip-feedback','ghost'):''}</div></form>`,'feedback');
}
function feedbackSummary(s){const f=s.feedback;if(!f||(!f.mood&&!f.effort&&!f.note))return '';return `<section class="feedback-summary"><h3>Dein Trainingsgefühl</h3><div class="feedback-chips">${f.mood?`<span><small>Stimmung</small><strong>${MOODS[f.mood-1]}</strong></span>`:''}${f.effort?`<span><small>Training empfunden</small><strong>${EFFORTS[f.effort-1]}</strong></span>`:''}</div>${f.note?`<p class="break">${esc(f.note)}</p>`:''}</section>`;}

async function requestWake(){try{if('wakeLock'in navigator)wakeLock=await navigator.wakeLock.request('screen');}catch(e){}}
function stopExerciseClock(){const a=state.active;if(!a?.timer)return;const p=G.next(a);if(p)a.items[p.i].sets[p.s].seconds=Math.max(1,Math.round((Date.now()-a.timer.startedAt)/1000));a.timer=null;save();}
function focusSettings(){const a=state.active;if(!a)return;stopExerciseClock();const p=G.next(a);openModal('Training anpassen',`<p class="meta">Änderungen gelten für diese Einheit. Abgeschlossene Sätze bleiben erhalten.</p><div class="inline-form"><label>Trainingsnotiz<textarea data-active-note>${esc(a.notes)}</textarea></label></div>${p?`<div style="margin-top:18px">${itemEditor(a.items[p.i],p.i,'active')}</div>${btn('Übungsanleitung ansehen','focus-guide','outline',`data-id="${a.items[p.i].exerciseId}"`)}`:`<div style="margin-top:18px">${a.items.map((it,i)=>itemEditor(it,i,'active')).join('')}</div>`}<div class="modal-actions">${btn('Zurück zum Training','close-settings','accent')}</div>`,'focus-settings');}
function earlyEnd(){stopExerciseClock();const a=state.active;if(!a)return;if(G.isActivity(a)){openActivityFinish();return;}openModal('Wie möchtest du weitermachen?',`<p>${G.doneCount(a)} Sätze sind abgeschlossen. Beim Speichern zählen nur diese Sätze.</p><div class="modal-actions">${G.doneCount(a)?btn('Abgeschlossene Sätze speichern','save-active','accent'):''}${btn('Mit eigenen Übungen fortführen','extend-early','outline')}${btn('Zum laufenden Training zurück','resume','outline')}${btn('Gesamtes Training verwerfen','discard-active','danger')}</div>`,'early-end');}
function newRecords(session){return session.items.map(it=>{const previous=G.best(state.sessions.filter(w=>w.id!==session.id),it.exerciseId,it.kind),current=G.best([session],it.exerciseId,it.kind);if(!current)return null;const better=!previous||it.kind==='reps'?(!!current&&(!previous||current.weight>previous.weight||current.weight===previous.weight&&current.reps>previous.reps)):it.kind==='time'?current.seconds>previous.seconds:current.distance>previous.distance;if(!better)return null;return{name:itemName(it),text:recordText(current,it.kind),first:!previous};}).filter(Boolean);}
function finishActive(feedback=null){G.validateFeedback(feedback);stopExerciseClock();const session=G.finish(state.active,state.active.finishedAt||Date.now()),records=newRecords(session);session.feedback=feedback;delete session.finishedAt;delete session.feedbackStage;const previousActive=state.active;state.sessions.push(session);state.active=null;if(!save()){state.sessions.pop();state.active=previousActive;throw Error('Die Einheit konnte nicht gespeichert werden. Bitte App geöffnet lassen.');}window.AndroidGym?.cancelRest();wakeLock?.release().catch(()=>{});closeModal();route='home';render();openModal('Training gespeichert',`<div class="recap"><div class="finish-icon">${icon('check')}</div><h2>${esc(workoutName(session))}</h2><p class="muted">${fmt(session.duration/60)} Minuten${G.isActivity(session)?'':' · '+G.doneCount(session)+' Sätze · '+session.items.length+' Übungen'}</p></div>${records.length?`<h3>${icon('trophy')} Deine Bestleistungen</h3><div class="record-list">${records.map(r=>`<div class="record-item">${icon('trophy')}<div><strong>${esc(r.name)}</strong><div class="meta">${r.first?'Erster Eintrag':'Neuer Rekord'} · ${r.text}</div></div></div>`).join('')}</div>`:''}<div class="modal-actions">${btn('Einheit ansehen','session','accent',`data-id="${session.id}"`)}${btn('Zur Übersicht','close-modal','outline')}</div>`,'recap');}
function openLanguage(){openModal('Sprache',`<div class="language-options">${btn('Deutsch','set-language',state.language==='de'?'accent':'outline','data-language="de"')}${btn('English','set-language',state.language==='en'?'accent':'outline','data-language="en"')}</div>`,'language');}
function openGoals(){const g=state.goals;openModal('Ziele & Erinnerungen',`<form id="goals-form" class="inline-form"><label>Einheiten pro Woche<input type="number" name="weekly" min="1" max="21" value="${g.weekly}" required></label><label class="inline-check"><input name="reminders" type="checkbox" ${g.reminders?'checked':''}>An Trainingstage erinnern</label><div><span class="meta">Trainingstage</span><div class="goal-days">${(state.language==='en'?['Sun','Mon','Tue','Wed','Thu','Fri','Sat']:['So','Mo','Di','Mi','Do','Fr','Sa']).map((d,i)=>`<label class="day-toggle"><input type="checkbox" name="day" value="${i}" ${g.days.includes(i)?'checked':''}>${d}</label>`).join('')}</div></div><label>Uhrzeit<input name="time" type="time" value="${g.time}" required></label><div class="note">${window.AndroidGym?'Android erinnert dich auch bei geschlossener App. Benachrichtigungen müssen erlaubt sein; der Zeitpunkt kann durch Energiesparfunktionen leicht verzögert werden.':'In dieser Browser-Version erscheinen Erinnerungen, solange die App geöffnet ist. Die Android-App unterstützt zusätzlich Systembenachrichtigungen bei geschlossener App.'}</div><button class="btn accent" type="submit">Ziele speichern</button></form>`,'goals');}
function render(motion=''){document.documentElement.lang=state.language;document.title=state.language==='en'?'Setwerk · Your training':'Setwerk · Dein Training';const a=$('#app');if(route==='focus'){a.innerHTML=localizeHTML(focus());if(motion)document.querySelector('.focus-main')?.classList.add('motion-'+motion);}else{const pages={home,templates,select:()=>templates(true),editor:()=>editor(false),manual:()=>editor(true),exercises,calendar:calendarPage,progress};a.innerHTML=localizeHTML(shell((pages[route]||home)()));}if(storageFault||writeFault)showStorageError();window.dispatchEvent(new Event('setwerk:render'));}
function currentItems(context){return context==='active'?state.active.items:draft.items;}
function refreshEditor(context){if(context==='active'){save();focusSettings();}else{persistDraft();render();}}
function validateDraft(){const cardio=draft.category==='Ausdauer',strength=['Kraft','Kraft-Ausdauer'].includes(draft.category);if(cardio){G.validateCardio(cardioFromDraft());G.validateDuration(Number(draft.durationMinutes));}if((!cardio||draft.mode==='template')&&!draft.name.trim())throw Error(draft.category==='Ballsport'?'Bitte eine Sportart eintragen.':'Bitte einen Namen eingeben.');if(!G.CATEGORIES.includes(draft.category))throw Error('Bitte eine Trainingsart wählen.');if(strength&&(draft.mode==='template'||draft.items.length))G.validateItems(draft.items);if(draft.category==='Ballsport')G.validateDuration(Number(draft.durationMinutes));if(draft.mode==='manual'){if(!/^\d{4}-\d{2}-\d{2}$/.test(draft.date)||Number.isNaN(new Date(draft.date).getTime())||draft.date>G.localDate())throw Error('Bitte ein gültiges Datum bis heute auswählen.');if(!Number.isFinite(+draft.durationMinutes)||+draft.durationMinutes<=0)throw Error('Bitte eine Dauer über null Minuten eintragen.');}}

function saveDraft(){validateDraft();const before=G.clone(state),beforeDraft=G.clone(draft),beforeRoute=route;const record={...G.clone(draft),name:draft.name.trim()};delete record.cardioForm;delete record.mode;delete record.editId;if(draft.category==='Ausdauer'){record.cardio=cardioFromDraft();record.items=[];delete record.sport;}else{delete record.cardio;if(draft.category==='Ballsport'){record.sport=record.name;record.items=[];}else delete record.sport;}if(draft.mode==='manual'){if(draft.category==='Ausdauer'){record.cardio=cardioFromDraft();const old=state.sessions.find(s=>s.id===draft.editId);record.items=old?.category==='Ausdauer'?G.clone(old.items):[];if(!record.name||old?.cardio&&(old.name===old.cardio.type||old.name===old.cardio.other))record.name=record.cardio.type==='Sonstige'?record.cardio.other:record.cardio.type;}else{delete record.cardio;if(draft.category==='Ballsport'){const old=state.sessions.find(s=>s.id===draft.editId);if(old?.category==='Ballsport')record.items=G.clone(old.items);}}const now=Date.now();record.id=draft.editId||G.uid();record.duration=Math.round(draft.durationMinutes*60);record.startedAt=new Date(draft.date+'T12:00:00').getTime();record.endedAt=record.startedAt+record.duration*1000;record.recordedAt=now;record.manual=true;record.items=record.items.map(it=>({...it,sets:it.sets.map(s=>({...s,done:true,skipped:false}))}));state.sessions=state.sessions.filter(s=>s.id!==record.id);state.sessions.push(record);selectedDate=record.date;calMonth=record.date.slice(0,7);route='calendar';}else{state.templates=state.templates.filter(t=>t.id!==record.id);state.templates.push(record);route='templates';}draft=null;delete state.draft;if(!save()){state=before;draft=beforeDraft;route=beforeRoute;throw Error('Speichern fehlgeschlagen. Dein Entwurf bleibt geöffnet.');}render();window.scrollTo(0,0);toast('Gespeichert.');}
const actions={
'activity-finish':openActivityFinish,
'toggle-language':()=>{const previous=state.language;state.language=previous==='de'?'en':'de';if(!save()){state.language=previous;render();return;}render();document.querySelector('[data-action="toggle-language"]')?.focus();},'language':openLanguage,'set-language':b=>{const lang=b.dataset.language;if(!['de','en'].includes(lang))throw Error('Bitte eine Sprache auswählen.');state.language=lang;if(!save())throw Error('Speichern fehlgeschlagen');closeModal();render();},
'nav':b=>navigate(b.dataset.route),'nav-exercises':()=>navigate('exercises'),'nav-calendar':()=>navigate('calendar'),'start-select':()=>navigate('select'),'new-template':()=>newDraft('template'),'manual-new':()=>{if(selectedDate>G.localDate())selectedDate=G.localDate();newDraft('manual');},
'close-modal':()=>{if(modalKind==='feedback'&&state.active){delete state.active.feedbackStage;delete state.active.finishedAt;save();}closeModal();if(route==='focus')render();},'close-settings':()=>{const a=state.active;for(const it of a.items){if(!Number.isFinite(+it.rest)||it.rest<0||it.rest>3600)throw Error('Pause muss zwischen 0 und 3600 Sekunden liegen.');for(const s of it.sets)if(!s.skipped)G.validateSet(s,it.kind);}closeModal();save();render();},
'resume-draft':()=>{draft=state.draft;closeModal();route=draft.mode==='manual'?'manual':'editor';render();},'replace-draft':b=>{draft=null;createDraft(b.dataset.mode);},'discard-draft':()=>openModal('Entwurf verwerfen?',`<p>Der aktuelle Entwurf wird entfernt. Eine bereits gespeicherte Vorlage oder Einheit bleibt erhalten.</p><div class="modal-actions">${btn('Entwurf verwerfen','confirm-discard-draft','danger')}${btn('Weiter bearbeiten','close-modal','outline')}</div>`),
'confirm-discard-draft':()=>{draft=null;delete state.draft;save();navigate('home');},
'edit-template':b=>editTemplate(b.dataset.id),'copy-template':b=>{const t=G.clone(state.templates.find(t=>t.id===b.dataset.id));t.id=G.uid();t.name+=' (Kopie)';state.templates.push(t);if(save()){render();toast('Vorlage kopiert.');}},
'delete-template':b=>openModal('Vorlage löschen?',`<p>Abgeschlossene Trainingseinheiten bleiben im Kalender erhalten.</p><div class="modal-actions">${btn('Vorlage löschen','confirm-delete-template','danger',`data-id="${b.dataset.id}"`)}${btn('Abbrechen','close-modal','outline')}</div>`),
'confirm-delete-template':b=>{state.templates=state.templates.filter(t=>t.id!==b.dataset.id);save();closeModal();render();},
'pick-exercise':b=>openPicker(b.dataset.target||'draft'),
'choose-exercise':b=>{const ex=exBy(b.dataset.id);if(!ex)throw Error('Übung nicht gefunden.');chooseExercise(ex);},
'custom-exercise':b=>openCustom(b.dataset.return==='picker'),
'add-set':b=>{const context=b.dataset.context,it=currentItems(context)[+b.dataset.item];if(it.sets.length>=50)throw Error('Maximal 50 Sätze pro Übung.');const last=it.sets.at(-1)||G.setDefaults(it.kind);it.sets.push({...G.clone(last),id:G.uid(),done:false,skipped:false,completedAt:null});refreshEditor(context);},
'remove-set':b=>{const context=b.dataset.context,it=currentItems(context)[+b.dataset.item];if(it.sets.length<=1)throw Error('Mindestens ein Satz muss erhalten bleiben.');const s=it.sets[+b.dataset.set];if(context==='active'&&(s.done||s.skipped))return;it.sets.splice(+b.dataset.set,1);refreshEditor(context);},
'remove-item':b=>{draft.items.splice(+b.dataset.item,1);persistDraft();render();},'move-item':b=>{const i=+b.dataset.item,j=i+(+b.dataset.dir);if(j<0||j>=draft.items.length)return;[draft.items[i],draft.items[j]]=[draft.items[j],draft.items[i]];persistDraft();render();},
'exercise':b=>exerciseDetail(b.dataset.id),'more-exercises':()=>{limit+=60;$('#exercise-results').innerHTML=localizeHTML(exerciseResults(filteredExercises(search,muscle,equipment)));},
'month':b=>{const manual=b.dataset.mode==='manual',[y,m]=(manual?manualMonth:calMonth).split('-').map(Number),d=new Date(y,m-1+(+b.dataset.dir),1,12);if(manual)manualMonth=G.localDate(d).slice(0,7);else calMonth=G.localDate(d).slice(0,7);render();},
'select-date':b=>{if(b.dataset.mode==='manual'){draft.date=b.dataset.date;persistDraft();}else selectedDate=b.dataset.date;render();},
'session':b=>sessionDetail(b.dataset.id),'repeat-session':b=>{const previous=state.sessions.find(s=>s.id===b.dataset.id);state.active=G.start(previous);if(!save())throw Error('Training konnte nicht gespeichert werden.');route='focus';closeModal();render();requestWake();},'edit-session':b=>{const s=state.sessions.find(x=>x.id===b.dataset.id);draft=null;createDraft('manual',s);},
'session-template':b=>{const s=state.sessions.find(x=>x.id===b.dataset.id);draft={id:G.uid(),mode:'template',name:s.name,category:s.category,notes:s.notes,items:G.clone(s.items).map(it=>({...it,uid:G.uid(),sets:it.sets.map(set=>({...set,id:G.uid(),done:false,skipped:false,completedAt:null}))}))};persistDraft();route='editor';closeModal();render();},
'delete-session':b=>openModal('Einheit löschen?',`<p>Diese Einheit und ihre Sätze werden gelöscht. Rekorde und Fortschritte werden neu berechnet.</p><div class="modal-actions">${btn('Einheit endgültig löschen','confirm-delete-session','danger',`data-id="${b.dataset.id}"`)}${btn('Abbrechen','close-modal','outline')}</div>`),
'confirm-delete-session':b=>{state.sessions=state.sessions.filter(s=>s.id!==b.dataset.id);save();closeModal();render();toast('Einheit gelöscht.');},
'goals':openGoals,
'start-template':async b=>{if(state.active){navigate('focus');return;}const t=state.templates.find(t=>t.id===b.dataset.id);state.active=G.start(t);if(!save())throw Error('Training konnte nicht gespeichert werden.');route='focus';closeModal();render();await requestWake();},
'resume':()=>{closeModal();route='focus';render();requestWake();},'focus-settings':focusSettings,'early-end':earlyEnd,
'focus-guide':b=>{const ex=exBy(b.dataset.id);openModal(esc(exName(ex)),`<ol class="guide">${instructionsFor(ex).map(t=>`<li>${esc(t)}</li>`).join('')}</ol>${btn('Zurück zu den Einstellungen','focus-settings','outline')}`);},
'complete-set':()=>{stopExerciseClock();const result=G.complete(state.active);if(!result)return;save();if(result.rest>0)window.AndroidGym?.scheduleRest(state.active.rest.until);navigator.vibrate?.(30);nextMotion=result.next&&result.completed.i!==result.next.i?'exercise':'set';render(result.rest?'':nextMotion);if(!result.rest)nextMotion='';},
'skip-rest':()=>{state.active.rest=null;window.AndroidGym?.cancelRest();save();render(nextMotion||'set');nextMotion='';},
'exercise-timer':()=>{if(state.active.timer)stopExerciseClock();else{state.active.timer={startedAt:Date.now()};save();}render();},
'extend-final':()=>openPicker('active'),'extend-early':()=>openPicker('extend-early'),
'save-active':()=>openFeedback(),'skip-feedback':()=>finishActive(null),'edit-feedback':b=>openFeedback(b.dataset.id),
'start-spontaneous':async()=>{if(state.active){navigate('focus');return;}state.active=G.spontaneous();if(!save())throw Error('Training konnte nicht gespeichert werden.');route='focus';closeModal();render('exercise');await requestWake();},
'edit-value':b=>editValue(b.dataset.field),'replace-exercise':()=>{stopExerciseClock();openPicker('replace-active');},
'discard-active':()=>openModal('Training verwerfen?',`<p>Alle Sätze dieser laufenden Einheit werden entfernt.</p><div class="modal-actions">${btn('Training verwerfen','confirm-discard-active','danger')}${btn('Zum Training zurück','resume','outline')}</div>`),
'confirm-discard-active':()=>{state.active=null;window.AndroidGym?.cancelRest();save();wakeLock?.release().catch(()=>{});closeModal();route='home';render();},
};
let exportSelection=null,importBundle=null,importReadSerial=0;
function openExport(kind,id){
 const record=(kind==='template'?state.templates:state.sessions).find(w=>w.id===id);if(!record)return;
 exportSelection={kind,id};
 openModal('Workout teilen',`<div class="inline-form"><h3 class="break">${esc(workoutName(record))}</h3><p class="meta">Datei oder Code enthalten das ausgewählte Workout und können offline weitergegeben werden.</p><label class="inline-check"><input type="checkbox" id="share-personal">Notizen, RPE/RIR und Trainingsgefühl einschließen</label><div class="modal-actions">${btn('Datei speichern','export-file','accent')}<span id="share-file-slot"></span>${btn('Code anzeigen','export-code','outline')}</div><div id="export-code-slot"></div><p class="field-help">Die Datei wird auf deinem Gerät gespeichert. Importiere sie in Setwerk über „Workout importieren“.</p></div>`,'export');
 refreshShareButton();
}
function selectedExport(){const r=(exportSelection.kind==='template'?state.templates:state.sessions).find(w=>w.id===exportSelection.id);if(!r)throw Error('Workout nicht gefunden.');return SetwerkTransfer.pack(r,exportSelection.kind,allExercises(),!!$('#share-personal')?.checked);}
function exportFile(){const data=selectedExport(),name=data.workout.name.replace(/[^\p{L}\p{N}_-]+/gu,'-').slice(0,70)||'Workout';return new File([SetwerkTransfer.json(data)],name+'.setwerk.json',{type:'application/json'});}
function refreshShareButton(){const slot=$('#share-file-slot');if(!slot)return;try{slot.innerHTML=localizeHTML(navigator.canShare?.({files:[exportFile()]})?btn('Datei teilen','share-file','outline'):'');}catch(e){slot.textContent='';}}
function showExportCode(){const code=SetwerkTransfer.code(selectedExport());$('#export-code-slot').innerHTML=localizeHTML(`<label>Workout-Code<textarea id="workout-code" class="workout-code" readonly spellcheck="false">${esc(code)}</textarea></label><div class="modal-actions">${btn('Code kopieren','copy-workout-code','outline')}</div><p class="field-help">Der Code enthält alle Workout-Daten und kann deshalb länger sein. Vollständig kopieren.</p>`);}
function downloadWorkout(){const file=exportFile(),url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=file.name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Datei zum Speichern geöffnet.');}
async function shareWorkoutFile(){try{await navigator.share({files:[exportFile()],title:tr('Workout teilen')});}catch(e){if(e.name!=='AbortError')toast('Teilen ist hier nicht verfügbar. Bitte „Datei speichern“ verwenden.');}}
async function copyWorkoutCode(){const input=$('#workout-code');try{if(!navigator.clipboard?.writeText)throw Error();await navigator.clipboard.writeText(input.value);toast('Code kopiert.');}catch(e){input.focus();input.select();input.setSelectionRange(0,input.value.length);toast('Bitte den markierten Code manuell kopieren.');}}
function openImport(){importBundle=null;openModal('Workout importieren',`<div class="inline-form"><p class="meta">Wähle eine Setwerk-Datei oder füge einen vollständigen Workout-Code ein.</p><label>Datei auswählen<input id="workout-import-file" type="file" accept=".json,.setwerk,.txt,application/json,text/plain"></label><div class="import-or">oder</div><label>Workout-Code<textarea id="workout-import-code" class="workout-code" spellcheck="false" placeholder="SW1.…"></textarea></label>${btn('Vorschau anzeigen','preview-import','accent')}<p id="import-error" class="import-error" role="alert"></p><div id="import-preview"></div></div>`,'import');}
function clearImportPreview(){importReadSerial++;importBundle=null;$('#import-preview').innerHTML='';$('#import-error').textContent='';}
function previewImport(text){clearImportPreview();try{importBundle=SetwerkTransfer.parse(text);const b=importBundle,w=b.workout;$('#import-preview').innerHTML=localizeHTML(`<section class="import-preview"><span class="eyebrow">IMPORTVORSCHAU</span><h3 class="break">${esc(w.name)}</h3>${badge(w.category)}${b.kind==='session'?`<p class="meta">${dateLabel(w.date)} · ${fmt(w.duration/60)} Min.</p>`:''}${w.cardio?cardioSummary(w.cardio):w.sport?`<p class="meta">${esc(w.sport)} · ${fmt(w.durationMinutes||w.duration/60)} Min.</p>`:w.items.map(it=>`<div class="import-exercise"><strong>${esc(it.exercise.name)}</strong><p class="meta">${it.sets.length} Sätze · ${time(it.rest)} Pause</p>${it.sets.map(set=>`<div class="meta">${setText(set,{kind:it.exercise.kind})}</div>`).join('')}${it.notes?`<p class="break">${esc(it.notes)}</p>`:''}</div>`).join('')}${w.notes?`<p class="break">${esc(w.notes)}</p>`:''}${feedbackSummary(w)}<p class="field-help">Der Import erstellt einen neuen Eintrag. Bestehende Daten bleiben erhalten.</p>${b.kind==='session'?'<p class="field-help">„In Kalender übernehmen“ zählt die Einheit zu deinen absolvierten Trainings. Für Pläne von Freunden „Als Vorlage importieren“ wählen.</p>':''}<div class="modal-actions">${w.items.length&&!w.cardio||b.kind==='template'?btn('Als Vorlage importieren','confirm-import','accent','data-target="template"'):''}${b.kind==='session'?btn('In Kalender übernehmen','confirm-import','outline','data-target="session"'):''}</div></section>`);}catch(e){importBundle=null;$('#import-error').textContent=tr(e.message);}}
async function readWorkoutFile(file){clearImportPreview();if(!file)return;if(file.size>SetwerkTransfer.MAX_BYTES){$('#import-error').textContent=tr('Die Datei oder der Code ist zu groß (maximal 1 MB).');return;}const current=$('#workout-import-file'),serial=importReadSerial;try{const text=typeof file.text==='function'?await file.text():await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsText(file);});if(current!==$('#workout-import-file')||serial!==importReadSerial)return;$('#workout-import-code').value='';previewImport(text);}catch(e){if(current===$('#workout-import-file'))$('#import-error').textContent=tr('Datei konnte nicht gelesen werden.');}}
function confirmImport(target){if(!importBundle)return;const data=SetwerkTransfer.prepareImport(importBundle,target,allExercises()),before=G.clone(state);state.customExercises.push(...data.customExercises);state[target==='template'?'templates':'sessions'].push(data.record);if(!save()){state=before;throw Error('Speichern fehlgeschlagen.');}importBundle=null;closeModal();if(target==='session'){selectedDate=data.record.date;calMonth=selectedDate.slice(0,7);route='calendar';}else route='templates';render();toast('Workout importiert.');}
Object.assign(actions,{'export-template':b=>openExport('template',b.dataset.id),'export-session':b=>openExport('session',b.dataset.id),'export-file':downloadWorkout,'share-file':shareWorkoutFile,'export-code':showExportCode,'copy-workout-code':copyWorkoutCode,'import-workout':openImport,'preview-import':()=>previewImport($('#workout-import-code').value),'confirm-import':b=>confirmImport(b.dataset.target)});
document.addEventListener('input',e=>{if(e.target.id==='workout-import-code')clearImportPreview();});
document.addEventListener('change',e=>{if(e.target.id==='workout-import-file')readWorkoutFile(e.target.files?.[0]);else if(e.target.id==='share-personal'){refreshShareButton();if($('#workout-code'))showExportCode();}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;try{await actions[b.dataset.action]?.(b);}catch(err){errorDisplay(err);}});
document.addEventListener('input',e=>{const t=e.target;try{if(t.id==='exercise-search'){search=t.value;limit=60;$('#exercise-results').innerHTML=localizeHTML(exerciseResults(filteredExercises(search,muscle,equipment)));}else if(t.id==='picker-search'){pickerSearch=t.value;$('#picker-results').innerHTML=localizeHTML(exerciseRows(filteredExercises(pickerSearch,pickerMuscle,''),true)||'<p class="meta">Keine passende Übung gefunden.</p>');}else if(t.dataset.draft){const f=t.dataset.draft;draft[f]=f==='durationMinutes'?Number(t.value):t.value;persistDraft();}else if(t.dataset.cardio){ensureCardioForm();draft.cardioForm[t.dataset.cardio]=t.value;if(['count','workSeconds','restSeconds'].includes(t.dataset.cardio))updateIntervalDuration();persistDraft();}else if(t.hasAttribute('data-active-note')){state.active.notes=t.value;save();}else if(t.dataset.context){const it=currentItems(t.dataset.context)[+t.dataset.item],f=t.dataset.field,target=t.dataset.set!==undefined?it.sets[+t.dataset.set]:it;target[f]=['reps','weight','seconds','distance','rest'].includes(f)?Number(t.value):['rpe','rir'].includes(f)?(t.value===''?'':Number(t.value)):t.value;t.dataset.context==='active'?save():persistDraft();}}catch(err){errorDisplay(err);}});
document.addEventListener('change',e=>{const t=e.target;try{if(t.dataset.draft==='category'){if(draft.category==='Ausdauer')ensureCardioForm();persistDraft();render();}else if(t.dataset.cardio==='type'||t.dataset.cardio==='mode'){if(t.dataset.cardio==='mode')updateIntervalDuration();persistDraft();render();}else if(t.id==='exercise-metric'){exerciseDetail(selectedExercise,t.value);}else if(t.id==='muscle-filter'){muscle=t.value;limit=60;$('#exercise-results').innerHTML=localizeHTML(exerciseResults(filteredExercises(search,muscle,equipment)));}else if(t.id==='equipment-filter'){equipment=t.value;limit=60;$('#exercise-results').innerHTML=localizeHTML(exerciseResults(filteredExercises(search,muscle,equipment)));}else if(t.id==='picker-muscle'){pickerMuscle=t.value;$('#picker-results').innerHTML=localizeHTML(exerciseRows(filteredExercises(pickerSearch,pickerMuscle,''),true));}else if(t.id==='manual-template'&&t.value){const tpl=state.templates.find(x=>x.id===t.value);if(draft.items.length){openModal('Übungen ersetzen?',`<p>Die Übungen des Entwurfs werden durch die ausgewählte Vorlage ersetzt.</p><div class="modal-actions">${btn('Vorlage übernehmen','load-manual-template','accent',`data-id="${tpl.id}"`)}${btn('Abbrechen','close-modal','outline')}</div>`);}else loadManualTemplate(tpl.id);}else if(t.dataset.draft==='date'){manualMonth=draft.date.slice(0,7);render();}}catch(err){errorDisplay(err);}});
function loadManualTemplate(id){const t=state.templates.find(t=>t.id===id);draft.items=G.clone(t.items);if(!draft.name.trim())draft.name=t.name;draft.category=t.category;if(G.isActivity(t))draft.durationMinutes=t.durationMinutes||60;delete draft.cardioForm;if(t.cardio)draft.cardio=G.clone(t.cardio);else delete draft.cardio;if(t.sport)draft.sport=t.sport;else delete draft.sport;persistDraft();closeModal();render();}actions['load-manual-template']=b=>loadManualTemplate(b.dataset.id);
document.addEventListener('submit',e=>{e.preventDefault();try{if(e.target.id==='value-form'){
 const f=new FormData(e.target),field=f.get('field'),value=Number(f.get('value')),p=G.next(state.active);if(!p)throw Error('Keine aktive Übung.');
 if(!['reps','weight','seconds','distance'].includes(field)||String(f.get('value')).trim()==='')throw Error('Bitte einen gültigen Wert eingeben.');
 const it=state.active.items[p.i],copy={...it.sets[p.s],[field]:value};G.validateSet(copy,it.kind);
 if(f.has('remaining'))it.sets.forEach(st=>{if(!st.done&&!st.skipped)st[field]=value;});else it.sets[p.s][field]=value;
 save();closeModal();render('value');
 }else if(e.target.id==='activity-finish-form'){
 const f=new FormData(e.target),a=state.active,minutes=Number(f.get('minutes'));G.validateDuration(minutes);const c=a.cardio?G.clone(a.cardio):null;if(c){c.distanceMeters=G.cardioHasDistance(c.type)&&f.get('distanceKm')!==''?Math.round(Number(f.get('distanceKm'))*1000):null;c.elevationMeters=G.cardioHasElevation(c.type)&&f.get('elevationM')!==''?Number(f.get('elevationM')):null;G.validateCardio(c);}a.actualDurationSeconds=Math.round(minutes*60);if(c)a.cardio=c;a.notes=String(f.get('notes')||'');openFeedback();
 }else if(e.target.id==='feedback-form'){
 const f=new FormData(e.target),feedback={mood:f.has('mood')?Number(f.get('mood')):null,effort:f.has('effort')?Number(f.get('effort')):null,note:String(f.get('feedbackNote')||'').trim()};G.validateFeedback(feedback);
 if(feedbackTarget==='active')finishActive(feedback);else{const session=state.sessions.find(s=>s.id===feedbackTarget);session.feedback=feedback;if(!save())throw Error('Speichern fehlgeschlagen');sessionDetail(session.id);}
 }else if(e.target.id==='editor-form'){saveDraft();}else if(e.target.id==='custom-form'){const f=new FormData(e.target),name=String(f.get('name')).trim(),equipment=String(f.get('equipment')).trim();if(!name||!equipment)throw Error('Bitte Name und Equipment ausfüllen.');if(allExercises().some(x=>x.name.toLowerCase()===name.toLowerCase()))throw Error('Eine Übung mit diesem Namen existiert bereits.');const ex={id:G.uid(),name,equipment,muscle:f.get('muscle'),kind:f.get('kind'),instructions:String(f.get('instructions')).split('\n').map(x=>x.trim()).filter(Boolean),custom:true};state.customExercises.push(ex);if(!save())throw Error('Übung konnte nicht gespeichert werden.');if(f.get('back')==='picker')chooseExercise(ex);else{closeModal();render();}toast('Eigene Übung gespeichert.');}else if(e.target.id==='goals-form'){const f=new FormData(e.target),weekly=Number(f.get('weekly')),days=f.getAll('day').map(Number),reminders=f.has('reminders'),timeValue=String(f.get('time'));if(!Number.isInteger(weekly)||weekly<1||weekly>21)throw Error('Bitte 1–21 Einheiten als Wochenziel wählen.');if(reminders&&!days.length)throw Error('Bitte mindestens einen Trainingstag auswählen.');if(!/^\d{2}:\d{2}$/.test(timeValue))throw Error('Bitte eine gültige Uhrzeit wählen.');state.goals={weekly,days,reminders,time:timeValue};if(!save())throw Error('Ziele konnten nicht gespeichert werden.');if(window.AndroidGym)AndroidGym.setReminders(JSON.stringify(state.goals));closeModal();render();toast('Ziele gespeichert.');}}catch(err){errorDisplay(err);}});
$('#modal').addEventListener('cancel',()=>{if(modalKind==='feedback'&&state.active){delete state.active.feedbackStage;delete state.active.finishedAt;save();}modalKind='';if(route==='focus')render();});
function tick(){const a=state.active;if(a&&$('#activity-clock'))$('#activity-clock').textContent=time(Math.floor((Date.now()-a.startedAt)/1000));if(a?.rest){const left=Math.ceil((a.rest.until-Date.now())/1000);if(left<=0){a.rest=null;save();navigator.vibrate?.([50,80,50]);if(route==='focus')render(nextMotion||'set');nextMotion='';}else{if($('#rest-clock'))$('#rest-clock').textContent=time(left);if($('#rest-bar'))$('#rest-bar').style.width=Math.min(100,left/a.rest.total*100)+'%';}}if(a?.timer&&$('#focus-primary'))$('#focus-primary').textContent=time(Math.floor((Date.now()-a.timer.startedAt)/1000));checkReminder();}
function checkReminder(){if(storageFault||window.AndroidGym||!state.goals.reminders)return;const now=new Date(),today=G.localDate(),key=today+'T'+state.goals.time,minutes=now.getHours()*60+now.getMinutes(),[h,m]=state.goals.time.split(':').map(Number);if(state.goals.days.includes(now.getDay())&&minutes>=h*60+m&&state.reminderSeen!==key){state.reminderSeen=key;save();toast('Dein Trainingstag: Zeit für deine nächste Einheit.');}}
window.addEventListener('setwerk:account-state',event=>{if(window.AndroidGym)return;state=G.migrateState(event.detail.state);storageFault=!!event.detail.storageError;writeFault=false;$('#storage-error')?.remove();draft=state.draft||null;if(event.detail.accountChanged){closeModal();route=state.active?'focus':'home';search='';limit=60;}render();if(state.active){requestWake();if(state.active.feedbackStage)openFeedback();}});
window.addEventListener('beforeunload',()=>{if(draft)state.draft=draft;save();});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){tick();if(state.active)requestWake();}});
// Read-only discovery and explicit UI staging through the same rendering actions.
if(document.modelContext?.registerTool){const registrations=[{name:'list_training_templates',title:'Trainingsvorlagen auflisten',description:'Liest die lokal gespeicherten Trainingsvorlagen. Startet kein Training.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('Keine Parameter erwartet.');return{templates:state.templates.map(t=>({id:t.id,name:t.name,exercises:t.items.length}))};}},{name:'open_exercise_details',title:'Übungsdetails anzeigen',description:'Zeigt Anleitung und lokale Trainingswerte einer vorhandenen Übung an.',inputSchema:{type:'object',properties:{exerciseId:{type:'string'}},required:['exerciseId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.exerciseId!=='string'||Object.keys(input).length!==1||!exBy(input.exerciseId))throw Error('Unbekannte Übung.');exerciseDetail(input.exerciseId);return{opened:input.exerciseId};}}];for(const t of registrations){try{Promise.resolve(document.modelContext.registerTool(t)).catch(()=>{});}catch(e){}}}
if('serviceWorker'in navigator&&!window.AndroidGym&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(()=>{});
render();setInterval(tick,250);if(state.active){requestWake();if(state.active.feedbackStage)openFeedback();}


